public static class TransferDiagnosticsTest {
    static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
    static void Check(bool ok,string why){if(!ok)throw new Exception("Transfer diagnostics: "+why);}
    static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}
    static void Set(object o,string n,object value){o.GetType().GetField(n,F).SetValue(o,value);}
    static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,F).Invoke(o,args);}
    static string Value(DiagnosticUiSnapshot s,string label){return s.Pages.SelectMany(p=>p.Panels).SelectMany(p=>p.Metrics).First(m=>m.Label==label).Value;}
    static void Unit(){
        var a=new CoreAdapter.FileTransferData{id=new string('a',32),peer=new string('b',64),name="same.bin",size=1000000,done=500000,state=3,sending=true,account=7,statisticsKnown=true,statisticsBytes=500000,durationMs=2000,rateBits=800000,etaReliable=true};
        var b=new CoreAdapter.FileTransferData{id=new string('c',32),peer=a.peer,name=a.name,size=1000000,done=20,state=3,sending=true,account=7};var identity=new TransferDiagnosticIdentity("profile-one",a);var history=new TransferDiagnosticHistory();
        Func<string,DiagnosticUiSnapshot> read=scope=>TransferDiagnosticProjection.Read(identity,scope,new[]{b,a},"transfer="+a.id+" sending=1 size=1000000 read_us=100 ack_wait_ticks=20 journal_all_transfers_us=20000","N/A — route not bound",false,history);
        var s=read("profile-one");Check(Value(s,"Confirmed bytes / total")=="500000 / 1000000 bytes"&&Value(s,"Current payload rate")=="0.8 Mbps"&&Value(s,"Average payload rate")=="2 Mbps","confirmed accounting exact identity not same filename");Check(Value(s,"Read")=="100 µs cumulative"&&Value(s,"Journal persistence").Contains("ALL transfers")&&Value(s,"Actual in-flight chunks").Contains("Not instrumented"),"counter attribution and missing fields");Check(Value(s,"Local receiver write").Contains("Not instrumented"),"sender never claims remote disk cost");
        var timed=TransferDiagnosticProjection.Read(identity,"profile-one",new[]{a},"transfer="+a.id+" sending=1 size=1000000 ack_samples=4 ack_turnaround_us=10000 sender_idle_samples=4 sender_ack_to_send_us=8000 journal_selected_commits=8","unavailable",false,null);
        Check(Value(timed,"ACK turnaround (mean)")=="2.5 ms"&&Value(timed,"ACK arrival to next TLS submission (mean)")=="2 ms"&&Value(timed,"Local receiver dispatch").Contains("Not instrumented"),"measured timing units and local/remote boundary");
        var pipeline=TransferDiagnosticProjection.Read(identity,"profile-one",new[]{a},"transfer="+a.id+" sending=1 size=1000000 effective_chunk_bytes=65536 effective_window=8 outstanding_chunks=3","unavailable",false,null);
        Check(Value(pipeline,"Protocol chunk maximum (read-only)").StartsWith("65,536")&&Value(pipeline,"Maximum payload in-flight chunks (read-only)").StartsWith("8 ")&&Value(pipeline,"Actual in-flight chunks").StartsWith("3 "),"negotiated pipeline projection not legacy constants");
        Check(Value(read("profile-one"),"ACK turnaround (mean)").Contains("Waiting for samples"),"missing timing is not invented zero latency");
        Check(read("profile-two").Banner.Contains("context changed"),"profile isolation");a.sending=false;Check(read("profile-one").Banner.Contains("Not retained"),"direction isolation");a.sending=true;a.account=8;Check(read("profile-one").Banner.Contains("Not retained"),"account isolation");a.account=7;
        Check(TransferDiagnosticProjection.Counters("transfer="+a.id+" sending=0 size=1000000 read_us=777",a).Count==0,"owner direction mismatch");
        foreach(int state in new[]{3,4,5,6,8}){a.state=state;s=read("profile-one");Check(!s.Sample&&Value(s,"State")==ChatAttachmentProjection.Status(a),"actual state");if(state!=3)Check(Value(s,"Current payload rate")=="0 Mbps"&&Value(s,"ETA").Contains("inactive"),"inactive zero and no ETA");}a.state=3;a.rateBits=0;Check(Value(read("profile-one"),"Current payload rate")=="0 Mbps","stall zero");
        var now=DateTime.UtcNow.AddSeconds(-700);for(int i=0;i<700;i++)history.Observe(identity,a,now.AddSeconds(i));Check(history.Samples.Count==300&&history.Events.Count==1,"bounded graph and no duplicate lifecycle events");history.Paused=true;history.Observe(identity,a,DateTime.UtcNow);Check(history.Samples.Count==300,"pause collection only");history.Clear();Check(history.Samples.Count==0&&history.Events.Count==0,"cleanup");
        a.error="password=private123 token=private456";Check(!TransferDiagnosticProjection.Export(read("profile-one")).Contains("private"),"safe redaction");a.isArchive=true;Check(TransferDiagnosticProjection.Counters("transfer="+a.id+" sending=1 size=1000000 read_us=1",a).Count==0,"archive owner cannot borrow DM costs");
        Console.WriteLine("PASS: transfer identity/direction/account/profile isolation, state/byte/rate/ETA accounting, owner boundaries, sample bounds/pause/cleanup and privacy.");
    }
    static void Capture(FrameworkElement surface,string path){surface.UpdateLayout();var bmp=new RenderTargetBitmap((int)Math.Ceiling(surface.ActualWidth),(int)Math.Ceiling(surface.ActualHeight),96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen())dc.DrawRectangle(new VisualBrush(surface),null,new Rect(0,0,surface.ActualWidth,surface.ActualHeight));bmp.Render(drawing);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(path))png.Save(file);}
    public static async Task Run(DesktopApplication desktop,string directory){
        Unit();string oversized=Path.Combine(directory,"oversize-preflight.bin");using(var file=File.Create(oversized))file.SetLength(SelectedTransferFile.MaximumBytes);SelectedTransferFile.ValidateSize(oversized);using(var file=File.OpenWrite(oversized))file.SetLength(SelectedTransferFile.MaximumBytes+1);bool rejected=false;using(var unopened=new CoreAdapter()){try{unopened.FileTransfer(1,path:oversized);}catch(FileTooLargeException error){rejected=error.Message==FileTooLargeException.Explanation;}}Check(rejected,"oversize rejected before initiating native transfer; exact boundary allowed");File.Delete(oversized);SelectedTransferFile.ValidateSize(Path.Combine(directory,"missing-file"));
        bool savedOperating=(bool)Get(desktop,"fileTransferOperating");Set(desktop,"fileTransferOperating",true);
        try{using(var left=new CoreAdapter())using(var right=new CoreAdapter()){
            string a="",b="";ulong la=0,ra=0;bool lr=false,rr=false;var root=Path.Combine(directory,"transfer-diagnostics-native");Directory.CreateDirectory(root);
            left.Start(Path.Combine(root,"left"),0,"Transfer diagnostics sender");right.Start(Path.Combine(root,"right"),0,"Transfer diagnostics receiver");
            Action poll=()=>{foreach(var e in left.Poll()??new CoreEvent[0]){if(e.kind==0)a=e.peer;if(e.kind==18)la=(ulong)e.attempt;if(e.kind==2)Check(left.PinInitialAuthenticatedFriendIdentity(e.peer,(ulong)e.attempt,1),"left fixture pin");if(e.kind==3)lr=true;}foreach(var e in right.Poll()??new CoreEvent[0]){if(e.kind==0)b=e.peer;if(e.kind==18)ra=(ulong)e.attempt;if(e.kind==2)Check(right.PinInitialAuthenticatedFriendIdentity(e.peer,(ulong)e.attempt,1),"right fixture pin");if(e.kind==3)rr=true;}};
            var buffer=new byte[65536];Action pump=()=>{if(la>0&&ra>0){for(int i=0;i<8;i++){int n=left.TakeRelayOutput(la,buffer,0);if(n<=0)break;Check(right.RelayReceive(ra,buffer,n),"TLS input right");}for(int i=0;i<8;i++){int n=right.TakeRelayOutput(ra,buffer,0);if(n<=0)break;Check(left.RelayReceive(la,buffer,n),"TLS input left");}}poll();};
            Func<Func<bool>,Task> wait=async condition=>{var until=DateTime.UtcNow.AddSeconds(60);while(DateTime.UtcNow<until){pump();if(condition())return;await Task.Delay(5);}throw new Exception("Transfer fixture timeout");};await wait(()=>a.Length==64&&b.Length==64);
            Check(left.SetAuthenticatedFriends(71,1,new[]{new FriendConversationBinding{AccountId=72,CurrentPeerId=b,KnownPeerIds=new List<string>{b},ActiveFriend=true}})&&right.SetAuthenticatedFriends(72,1,new[]{new FriendConversationBinding{AccountId=71,CurrentPeerId=a,KnownPeerIds=new List<string>{a},ActiveFriend=true}}),"authenticated friend bindings");left.SetNetworkContext(1,"transfer-diagnostics-fixture");right.SetNetworkContext(1,"transfer-diagnostics-fixture");left.UpdateCandidates(b,"",0,"",0,true,1,true);right.UpdateCandidates(a,"",0,"",0,true,1,true);await wait(()=>la>0&&ra>0);Check(left.RelayReady(la,String.CompareOrdinal(a,b)>0)&&right.RelayReady(ra,String.CompareOrdinal(b,a)>0),"relay role binding");await wait(()=>lr&&rr);
            string path=Path.Combine(root,"same-name.bin");var bytes=new byte[10*1024*1024];new Random(142).NextBytes(bytes);File.WriteAllBytes(path,bytes);string downloads=Path.Combine(root,"downloads");Directory.CreateDirectory(downloads);var times=new List<double>();var cpu=new List<double>();bool screenshots=false;
            foreach(bool visible in new[]{false,true,true,false}){
                string id=left.FileTransfer(1,b,path:path);await wait(()=>right.FileTransfers().Any(r=>r.id==id&&r.state==2));right.FileTransfer(2,id:id,path:downloads);var clock=Stopwatch.StartNew();double cpuStart=Process.GetCurrentProcess().TotalProcessorTime.TotalMilliseconds;DateTime next=DateTime.MinValue;bool opened=false;
                await wait(()=>{
                    var sender=left.FileTransfers().Single(r=>r.id==id);if(visible&&DateTime.UtcNow>=next){next=DateTime.UtcNow.AddSeconds(1);Call(desktop,"CacheTransferDiagnostics",left.FileTransfers(),left.FileTransfer(11));Set(desktop,"attachmentTelemetry",left.FileTransfer(11));Set(desktop,"attachmentTelemetryAccount",0L);Set(desktop,"attachmentTelemetryGeneration",(ulong)Get(desktop,"authenticatedFriendSnapshotGeneration"));if(!opened){Call(desktop,"OpenTransferDiagnostics",sender);opened=true;}else{var h=(TransferDiagnosticHistory)Get(desktop,"transferDiagnosticHistory");h.Observe((TransferDiagnosticIdentity)Get(desktop,"transferDiagnosticIdentity"),sender,DateTime.UtcNow);}
                        if(!screenshots&&sender.state==3&&sender.done>0){var w=(Window)Get(desktop,"groupDiagnosticWindow");w.Width=1200;w.Height=880;Call(desktop,"RenderTransferDiagnostics");var tabs=(TabControl)Get(desktop,"groupDiagnosticTabs");for(int i=0;i<3;i++){tabs.SelectedIndex=i;w.UpdateLayout();Capture((FrameworkElement)w.Content,Path.Combine(directory,"transfer-"+new[]{"overview","network","pipeline"}[i]+".png"));}var bubble=new AttachmentCard{Transfer=sender};var frame=new Border{Child=bubble,Padding=new Thickness(14),Background=new SolidColorBrush(Color.FromRgb(30,44,55))};var bw=new Window{Content=frame,Resources=((Window)Get(desktop,"window")).Resources,Foreground=Brushes.White,Width=500,SizeToContent=SizeToContent.Height,Background=Brushes.Black,ShowInTaskbar=false};bw.Show();Capture(frame,Path.Combine(directory,"transfer-bubble.png"));bw.Close();screenshots=true;}
                    }return sender.state==4;
                });clock.Stop();times.Add(clock.Elapsed.TotalMilliseconds);cpu.Add(Process.GetCurrentProcess().TotalProcessorTime.TotalMilliseconds-cpuStart);
                var received=right.FileTransfers().Single(r=>r.id==id);Check(received.state==4&&received.done==bytes.Length&&File.ReadAllBytes(received.path).SequenceEqual(bytes),"verified final integrity sender and receiver");var ident=new TransferDiagnosticIdentity("native-right",received);var projected=TransferDiagnosticProjection.Read(ident,"native-right",right.FileTransfers(),right.FileTransfer(11),"Not instrumented",false,null);Check(Value(projected,"Direction").Contains("Receiver")&&Value(projected,"Integrity").Contains("verified"),"real receiver projection");Console.WriteLine("TRANSFER BENCHMARK diagnostics="+(visible?"open":"closed")+" bytes="+bytes.Length+" accepted_to_complete_ms="+clock.Elapsed.TotalMilliseconds.ToString("0.0")+" payload_mbps="+(bytes.Length*.008/clock.Elapsed.TotalMilliseconds).ToString("0.00")+" process_cpu_ms="+cpu.Last().ToString("0.0"));var win=(Window)Get(desktop,"groupDiagnosticWindow");if(win!=null)win.Close();
            }
            Check(screenshots,"real active transfer screenshots");
            var retained=left.FileTransfers().First(r=>r.state==4);Call(desktop,"CacheTransferDiagnostics",left.FileTransfers(),left.FileTransfer(11));Call(desktop,"OpenTransferDiagnostics",retained);var currentWindow=(Window)Get(desktop,"groupDiagnosticWindow");var currentTabs=(TabControl)Get(desktop,"groupDiagnosticTabs");Check(!((string)Call(desktop,"CurrentDiagnosticExport")).Contains("SAMPLE"),"normal transfer export real");
            currentTabs.SelectedIndex=6;currentWindow.UpdateLayout();var settings=(StackPanel)((ScrollViewer)((TabItem)currentTabs.SelectedItem).Content).Content;settings.Children.OfType<ComboBox>().First().SelectedIndex=1;Check(Value((DiagnosticUiSnapshot)Call(desktop,"ReadTransferDiagnostics"),"Average payload rate").Contains("MB/s"),"presentation units only");
            Set(desktop,"transfersDeveloperPreview",true);Call(desktop,"RefreshDiagnosticLayout");Check(((string)Call(desktop,"CurrentDiagnosticExport")).Contains("SAMPLE"),"explicit developer preview isolated");Set(desktop,"transfersDeveloperPreview",false);Call(desktop,"RefreshDiagnosticLayout");
            var generation=Get(desktop,"profileSessionGeneration");Set(desktop,"profileSessionGeneration",(ulong)generation+1);Check(((DiagnosticUiSnapshot)Call(desktop,"ReadTransferDiagnostics")).Banner.Contains("context changed"),"UI profile generation invalidation");Set(desktop,"profileSessionGeneration",generation);Set(desktop,"transferSnapshotUtc",DateTime.UtcNow.AddSeconds(-4));Check(((DiagnosticUiSnapshot)Call(desktop,"ReadTransferDiagnostics")).Banner.Contains("Not retained"),"stale snapshot never advertises live rate");currentWindow.Close();Check(((TransferDiagnosticHistory)Get(desktop,"transferDiagnosticHistory")).Samples.Count==0&&((List<Action>)Get(desktop,"transferViewRefreshes")).Count==0,"window handler/sample cleanup");
            string one=left.FileTransfer(1,b,path:path),two=left.FileTransfer(1,b,path:path);await wait(()=>right.FileTransfers().Count(r=>r.id==one||r.id==two)==2);var both=left.FileTransfers();Check(both.Single(r=>r.id==one).name==both.Single(r=>r.id==two).name,"actual concurrent identical filenames");left.FileTransfer(3,id:one);left.FileTransfer(3,id:two);await wait(()=>left.FileTransfers().Where(r=>r.id==one||r.id==two).All(r=>r.state==5));Check(!new TransferDiagnosticIdentity("same",both.Single(r=>r.id==one)).Matches("same",both.Single(r=>r.id==two)),"actual simultaneous identity selection");
            Console.WriteLine("PASS: actual packaged CoreAdapter mutual-TLS 10 MiB transfers, sender/receiver integrity, simultaneous same filenames/cancel, real completion, unit controls, preview isolation, stale/profile invalidation/cleanup and open/closed diagnostics benchmark. Host byte-pump fixture, NOT Android/Pi.");
        }}finally{Set(desktop,"fileTransferOperating",savedOperating);var w=(Window)Get(desktop,"groupDiagnosticWindow");if(w!=null)w.Close();}
    }
}
